1	export type Item = {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	};
7	
8	export type QuoteStep = {
9	  op: "quote";
10	  items: Item[];
11	};
12	
13	export type Damage = {
14	  itemType: string;
15	  amount: number;
16	};
17	
18	export type Incident = {
19	  cause: string;
20	  damages: Damage[];
21	};
22	
23	export type ClaimStep = {
24	  op: "claim";
25	  policy: number;
26	  incident: Incident;
27	};
28	
29	export type Step = QuoteStep | ClaimStep;
30	
31	export type Customer = {
32	  yearsWithMHPCO: number;
33	};
34	
35	export type Scenario = {
36	  customer: Customer;
37	  steps: Step[];
38	};
39	
40	export type ScenarioResult = {
41	  results: unknown[];
42	};
43	
44	const PROCESSING_FEE = 5;
45	
46	type ItemTypeSpec = {
47	  basePremium: number;
48	  insuranceValue: number;
49	};
50	
51	const ITEM_CATALOGUE: Record<string, ItemTypeSpec> = {
52	  sword: { basePremium: 100, insuranceValue: 1000 },
53	  amulet: { basePremium: 60, insuranceValue: 600 },
54	  staff: { basePremium: 80, insuranceValue: 800 },
55	  potion: { basePremium: 40, insuranceValue: 400 },
56	  rune: { basePremium: 25, insuranceValue: 250 },
57	  moonstone: { basePremium: 25, insuranceValue: 250 },
58	};
59	
60	const basePremiumOf = (item: Item): number =>
61	  ITEM_CATALOGUE[item.type].basePremium;
62	
63	const insuranceValueOf = (item: Item): number =>
64	  ITEM_CATALOGUE[item.type].insuranceValue;
65	
66	const BLOCK_SIZE = 3;
67	const BLOCK_BASE_PREMIUM = 60;
68	
69	const itemsGroupedByType = (items: Item[]): Item[][] => [
70	  ...items
71	    .reduce(
72	      (groupsByType, item) =>
73	        groupsByType.set(item.type, [
74	          ...(groupsByType.get(item.type) ?? []),
75	          item,
76	        ]),
77	      new Map<string, Item[]>(),
78	    )
79	    .values(),
80	];
81	
82	const formsABlock = (itemsAlike: Item[]): boolean =>
83	  itemsAlike.length === BLOCK_SIZE;
84	
85	const basePremiumOfItemsAlike = (itemsAlike: Item[]): number =>
86	  formsABlock(itemsAlike)
87	    ? BLOCK_BASE_PREMIUM
88	    : itemsAlike.reduce((total, item) => total + basePremiumOf(item), 0);
89	
90	const totalBasePremiumOf = (items: Item[]): number =>
91	  itemsGroupedByType(items).reduce(
92	    (total, itemsAlike) => total + basePremiumOfItemsAlike(itemsAlike),
93	    0,
94	  );
95	
96	const roundedUpInMHPCOsFavour = (premium: number): number => Math.ceil(premium);
97	
98	type Rule<Subject> = {
99	  appliesTo: (subject: Subject) => boolean;
100	  rate: number;
101	};
102	
103	const totalRateOf = <Subject,>(
104	  rules: Rule<Subject>[],
105	  subject: Subject,
106	): number =>
107	  rules.reduce(
108	    (rate, rule) => (rule.appliesTo(subject) ? rate + rule.rate : rate),
109	    0,
110	  );
111	
112	const CURSE_SURCHARGE_RATE = 0.5;
113	const HIGH_ENCHANTMENT_THRESHOLD = 5;
114	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
115	
116	const ITEM_SURCHARGE_RULES: Rule<Item>[] = [
117	  { appliesTo: (item) => item.cursed === true, rate: CURSE_SURCHARGE_RATE },
118	  {
119	    appliesTo: (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD,
120	    rate: HIGH_ENCHANTMENT_SURCHARGE_RATE,
121	  },
122	];
123	
124	const itemSurchargeOf = (item: Item): number =>
125	  basePremiumOf(item) * totalRateOf(ITEM_SURCHARGE_RULES, item);
126	
127	const totalItemSurchargeOf = (items: Item[]): number =>
128	  items.reduce((total, item) => total + itemSurchargeOf(item), 0);
129	
130	const LOYALTY_YEARS_THRESHOLD = 2;
131	const LOYALTY_DISCOUNT_RATE = -0.2;
132	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
133	
134	const FOLLOW_UP_DISCOUNT_RATE = -0.15;
135	
136	type PolicyContext = {
137	  customer: Customer;
138	  previousContracts: number;
139	};
140	
141	const POLICY_MODIFIER_RULES: Rule<PolicyContext>[] = [
142	  {
143	    appliesTo: ({ customer }) =>
144	      customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD,
145	    rate: LOYALTY_DISCOUNT_RATE,
146	  },
147	  { appliesTo: () => true, rate: FIRST_INSURANCE_SURCHARGE_RATE },
148	  {
149	    appliesTo: ({ previousContracts }) => previousContracts > 0,
150	    rate: FOLLOW_UP_DISCOUNT_RATE,
151	  },
152	];
153	
154	const quotePremium = (items: Item[], policy: PolicyContext): number => {
155	  const basePremium = totalBasePremiumOf(items);
156	
157	  return roundedUpInMHPCOsFavour(
158	    basePremium +
159	      totalItemSurchargeOf(items) +
160	      basePremium * totalRateOf(POLICY_MODIFIER_RULES, policy) +
161	      PROCESSING_FEE,
162	  );
163	};
164	
165	const DEDUCTIBLE = 100;
166	const CAP_MULTIPLIER = 2;
167	
168	const insuranceSumOf = (items: Item[]): number =>
169	  items.reduce((total, item) => total + insuranceValueOf(item), 0);
170	
171	const payoutCapOf = (items: Item[]): number =>
172	  CAP_MULTIPLIER * insuranceSumOf(items);
173	
174	const HALVED_REIMBURSEMENT_ENCHANTMENT_THRESHOLD = 8;
175	const HALVED_REIMBURSEMENT_RATE = 0.5;
176	const FULL_REIMBURSEMENT_RATE = 1;
177	
178	const reimbursementRateFor = (item: Item): number =>
179	  (item.enchantment ?? 0) >= HALVED_REIMBURSEMENT_ENCHANTMENT_THRESHOLD
180	    ? HALVED_REIMBURSEMENT_RATE
181	    : FULL_REIMBURSEMENT_RATE;
182	
183	const payoutForDamage = (damage: Damage, item: Item): number =>
184	  damage.amount * reimbursementRateFor(item) - DEDUCTIBLE;
185	
186	const isQuote = (step: Step): step is QuoteStep => step.op === "quote";
187	
188	type ClaimResult = {
189	  payout: number;
190	  remainingCap: number;
191	};
192	
193	const insuredItemFor = (damage: Damage, insuredItems: Item[]): Item =>
194	  insuredItems.find((item) => item.type === damage.itemType) as Item;
195	
196	const totalPayoutFor = (damages: Damage[], insuredItems: Item[]): number =>
197	  damages.reduce(
198	    (total, damage) =>
199	      total + payoutForDamage(damage, insuredItemFor(damage, insuredItems)),
200	    0,
201	  );
202	
203	const settleClaim = (incident: Incident, insuredItems: Item[]): ClaimResult => {
204	  const payout = totalPayoutFor(incident.damages, insuredItems);
205	
206	  return { payout, remainingCap: payoutCapOf(insuredItems) - payout };
207	};
208	
209	const insuredItemsOfPolicy = (steps: Step[], policy: number): Item[] => {
210	  const policyStep = steps[policy];
211	
212	  return isQuote(policyStep) ? policyStep.items : [];
213	};
214	
215	export const runScenario = (scenario: Scenario): ScenarioResult => {
216	  const quotesBefore = (index: number): number =>
217	    scenario.steps.slice(0, index).filter(isQuote).length;
218	
219	  return {
220	    results: scenario.steps.map((step, index) =>
221	      isQuote(step)
222	        ? {
223	            premium: quotePremium(step.items, {
224	              customer: scenario.customer,
225	              previousContracts: quotesBefore(index),
226	            }),
227	          }
228	        : settleClaim(
229	            step.incident,
230	            insuredItemsOfPolicy(scenario.steps, step.policy),
231	          ),
232	    ),
233	  };
234	};
